let duplicateHistory=[],duplicateHistoryFiles=[],duplicatePanelOpen=false;
function duplicatePool(){const saved=state.entries,ids=new Set(saved.map(e=>e.id)),sources=new Set(saved.map(e=>e.sourceKey).filter(Boolean));return [...saved,...importPreview.filter(e=>e.month===$('month').value&&!e.duplicate&&!ids.has(e.id)&&!(e.sourceKey&&sources.has(e.sourceKey)))]}
function duplicateResult(){return DuplicateCheck.scan(duplicatePool(),duplicateHistory,$('month').value,ruleBy,calculate)}
function duplicateRefresh(){const result=duplicateResult(),count=result.pairs.length;const scope=duplicateHistory.length?'另含临时往期对比'+duplicateHistory.length+'条':'未载入往期已发报表';const message=count?`发现${result.limited?'至少':''}${count}组疑似重复，请核对后再确认导入或导出。`:'未发现疑似重复。';for(const id of ['duplicateSummary','duplicateImportStatus']){$(id).textContent=message+' '+scope+'。';$(id).className='notice '+(count?'duplicate-warning':'')}
 $('duplicateCheckReport').textContent=count?'检查重复发放（'+(result.limited?'≥':'')+count+'）':'检查重复发放';$('duplicateCheckPanel').classList.toggle('hidden',!duplicatePanelOpen);$('duplicateCoverage').textContent='检查本次预览及本地记录'+(duplicateHistory.length?'、临时载入的往期明细':'')+'；未提供的历史不在检查范围。'+(result.reviewed?' 已确认不同绩效：'+result.reviewed+'组。':'')+(result.hourlyUnproven?' '+result.hourlyUnproven+'条课时记录缺少授课日期或时间依据，不仅凭同名老师和学生判重。':'');$('duplicateHistoryStatus').textContent=duplicateHistory.length?duplicateHistoryFiles.join('、')+' · '+duplicateHistory.length+'条（仅供对比，不计入本月工资，刷新页面后清除）':'未载入往期明细。';$('duplicateHistoryClear').disabled=!duplicateHistory.length;
 if(!duplicatePanelOpen)return;
 const detail=(d,which)=>{const e=d.entry,isPreview=!d.history&&!state.entries.some(x=>x.id===d.id);return `<div class="duplicate-record"><div class="actions" style="margin:0"><strong>${which} · ${esc(d.month||'月份未提供')}</strong><span class="pill ${d.history?'neutral':''}">${d.history?'往期已发对比':isPreview?'本次预览':'本地已保存'}</span></div><p><strong>${esc(d.teacher)}</strong> · ${esc(d.student)}</p><p>${esc(d.item)}${d.project?' · 项目'+esc(d.project):''}</p><p class="muted">${esc(d.version||'历史报表未含版本')}${d.ratio!==undefined?' · 比例'+Number((d.ratio*100).toFixed(6))+'%':''}${d.package?' · '+esc(d.package):''}</p><strong>¥${money(d.amount)}</strong><p class="muted">${esc(d.source||e.sourceLabel||'手动补录')}</p>${d.history?'<span class="muted">往期对比数据只读</span>':`<button type="button" class="danger" data-duplicate-delete="${esc(d.id)}" data-delete-kind="${isPreview?'preview':'saved'}">删除此条</button>`}</div>`};
 $('duplicatePairs').innerHTML=count?result.pairs.slice(0,100).map(pair=>`<article class="duplicate-pair"><h3>${esc(pair.reason)}</h3><div class="duplicate-compare">${detail(pair.a,'记录一')}${detail(pair.b,'记录二')}</div><div class="actions"><label class="duplicate-reason">确认说明<input maxlength="500" data-duplicate-reason="${esc(pair.token)}" placeholder="例如：同一项目分期结算，或不同申请批次"></label><button type="button" data-duplicate-accept="${esc(pair.token)}">确认是不同绩效</button></div></article>`).join('')+'<p class="muted">'+(count>100?'本次展示前100组；处理后自动展示后续记录。':'确认只对这两条记录及当前内容有效，金额、项目或老师变化后会重新检查。')+'</p>':'<p class="notice">无待处理的疑似重复。</p>';
}
function openDuplicateCheck(){duplicatePanelOpen=true;showTab('report');duplicateRefresh();$('duplicateCheckPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function duplicateGuard(){if(!duplicateResult().pairs.length)return true;openDuplicateCheck();toast('请先处理疑似重复：删除重复项，或说明原因确认是不同绩效。');return false}
function acceptDuplicatePair(token,reason){reason=String(reason||'').trim();if(!reason){toast('请填写确认说明，避免误放行重复绩效');return false}const pair=duplicateResult().pairs.find(p=>p.token===token);if(!pair){duplicateRefresh();toast('记录内容已变化，请按最新结果核对');return false}const ids=new Set([pair.a.id,pair.b.id]),records=[...new Set([...state.entries,...importPreview].filter(e=>ids.has(e.id)))],before=records.map(e=>({e,reviews:e.duplicateReviews,issue:e.importIssue}));for(const e of records){e.duplicateReviews=[...(e.duplicateReviews||[]).filter(r=>r.token!==token),{token,reason:reason.slice(0,500),at:new Date().toISOString()}];if(/^疑似同一项目重复结算/.test(e.importIssue||''))e.importIssue=''}try{if(records.some(e=>state.entries.includes(e)))save()}catch(err){for(const b of before){if(b.reviews===undefined)delete b.e.duplicateReviews;else b.e.duplicateReviews=b.reviews;b.e.importIssue=b.issue}toast('确认未保存：'+err.message);return false}render();renderReview();drawPreview();duplicateRefresh();toast('已记录确认说明，这两条按不同绩效处理');return true}
$('duplicateCheckReport').onclick=openDuplicateCheck;$('duplicateCheckImport').onclick=openDuplicateCheck;$('duplicateClose').onclick=()=>{duplicatePanelOpen=false;duplicateRefresh()};
$('duplicatePairs').addEventListener('click',event=>{const remove=event.target.closest('[data-duplicate-delete]');if(remove){const id=remove.dataset.duplicateDelete;const e=state.entries.find(e=>e.id===id);if(e&&e.month!==$('month').value){toast('历史月份记录请切换到对应月份核对，或删除本期重复项');return}removePerformance(id,remove.dataset.deleteKind);return}const accept=event.target.closest('[data-duplicate-accept]');if(accept){const token=accept.dataset.duplicateAccept,input=[...$('duplicatePairs').querySelectorAll('[data-duplicate-reason]')].find(e=>e.dataset.duplicateReason===token);acceptDuplicatePair(token,input?.value)}});
$('duplicateHistoryFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;const month=$('duplicateHistoryMonth').value;if(!/^\d{4}-\d{2}$/.test(month)){toast('请先选择这份往期报表的结算月份');event.target.value='';return}try{const result=DuplicateCheck.historyRows(await ExcelIO.read(file),month,file.name),ids=new Set(duplicateHistory.map(e=>e.id)),fresh=result.entries.filter(e=>!ids.has(e.id));duplicateHistory.push(...fresh);if(!duplicateHistoryFiles.includes(file.name))duplicateHistoryFiles.push(file.name);duplicateRefresh();toast('已临时载入'+fresh.length+'条往期明细，仅用于重复核对')}catch(err){toast('往期报表读取失败：'+err.message)}finally{event.target.value=''}};
$('duplicateHistoryClear').onclick=()=>{duplicateHistory=[];duplicateHistoryFiles=[];duplicateRefresh();toast('已移除临时往期对比，不影响工资记录')};
const commitBeforeDuplicate=$('commitImport').onclick;$('commitImport').onclick=event=>{if(duplicateGuard())return commitBeforeDuplicate(event)};
const exportBeforeDuplicate=exportPerformanceReport;exportPerformanceReport=async function(){if(duplicateGuard())return exportBeforeDuplicate()};for(const id of ['excelExport','excelExportTop','reportExport'])$(id).onclick=exportPerformanceReport;
const salaryExportBeforeDuplicate=$('salaryExport').onclick;$('salaryExport').onclick=event=>{if(duplicateGuard())return salaryExportBeforeDuplicate(event)};
const reportBeforeDuplicate=renderReport;renderReport=function(){reportBeforeDuplicate();duplicateRefresh()};
const previewBeforeDuplicate=drawPreview;drawPreview=function(){previewBeforeDuplicate();duplicateRefresh()};
const refreshBeforeDuplicate=refreshCampusState;refreshCampusState=function(){duplicateHistory=[];duplicateHistoryFiles=[];duplicatePanelOpen=false;refreshBeforeDuplicate();duplicateRefresh()};
function defaultHistoryMonth(){const [y,m]=$('month').value.split('-').map(Number);if(y&&m)$('duplicateHistoryMonth').value=new Date(Date.UTC(y,m-2,1)).toISOString().slice(0,7)}$('month').addEventListener('change',()=>{defaultHistoryMonth();duplicateRefresh()});defaultHistoryMonth();duplicateRefresh();
// Replace older one-off duplicate warnings with the pair review above.
{const records=state.entries.filter(e=>/^疑似同一项目重复结算/.test(e.importIssue||'')),before=records.map(e=>e.importIssue);if(records.length){for(const e of records)e.importIssue='';try{save();render();renderReview()}catch(err){records.forEach((e,i)=>e.importIssue=before[i]);toast('原重复提示保留，保存空间不足时请先备份。')}}}
